<span class="line"><span style="color:#89DDFF;">        </span><span style="color:#C792EA;">birthdayType</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">solar</span><span style="color:#89DDFF;">&quot;</span></span>
